    for i in range(j):
        if s[i] < s[j] and costs[i] < min_left_cost:
            min_left_cost = costs[i]

    # If we found a valid left display, find the minimum cost for a display k > j with s_k > s_j
    if min_left_cost != float('inf'):
        min_right_cost = float('inf')
        for k in range(j + 1, n):
            if s[k] > s[j] and costs[k] < min_right_cost:
                min_right_cost = costs[k]

        # If we found a valid right display
        if min_right_cost != float('inf'):
            total_cost = min_left_cost + min_right_cost + costs[j]
            if total_cost < min_cost:
                min_cost = total_cost

if min_cost == float('inf'):
    print(-1)
else:
    print(min_cost)
