import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Count how many coins we have of each power of 2
    power_count = {}
    for _ in range(n):
        coin = int(next(it))
        power = coin.bit_length() - 1
        if power not in power_count:
            power_count[power] = 0
        power_count[power] += 1

    results = []
    for _ in range(q):
        b = int(next(it))

        # Check if we can make b
        possible = True
        needed = 0

        # For each power of 2 in b's binary representation
        for power in range(31):  # Since b <= 1e9 < 2^31
            if (b >> power) & 1:
                if power not in power_count:
                    possible = False
                    break
                # We need at least one coin of this power
                if power_count[power] == 0:
                    possible = False
                    break
                needed += 1

        if possible:
            results.append(str(needed))
        else:
            results.append("-1")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

