import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    q = int(next(it))

    # Count coins by power of 2
    power_count = {}
    for _ in range(n):
        coin = int(next(it))
        power = coin.bit_length() - 1
        if power not in power_count:
            power_count[power] = 0
        power_count[power] += 1

    results = []
    for _ in range(q):
        b = int(next(it))

        # Count how many coins we need of each power to make b
        needed = [0] * 32  # For 32-bit numbers

        # For each power of 2 in b's binary representation
        for power in range(31):
            if (b >> power) & 1:
                needed[power] += 1

        # Check if we have enough coins
        can_make = True

        # Start from the lowest power and work up
        for power in range(31):
            # First, we need at least 'needed' coins of this power
            if needed[power] > power_count.get(power, 0):
                can_make = False
                break

            # Use up the coins we have for this power
            # Remaining coins = coins we have - coins needed for this power
            remaining = power_count.get(power, 0) - needed[power]

            # Carry over to higher powers
            if remaining > 0:
                needed[power + 1] += remaining

        if can_make:
            results.append(str(sum(needed)))
        else:
            results.append("-1")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

