import sys
import bisect

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    s = next(it)  # should be length k
    char_positions = {}
    for i, ch in enumerate(s, start=1):
        if ch not in char_positions:
            char_positions[ch] = []
        char_positions[ch].append(i)

    for _ in range(n):
        c = next(it)
        m = len(c)
        total = 0
        for idx in range(1, m+1):
            char = c[idx-1]
            if char not in char_positions:
                total += m
            else:
                pos_list = char_positions[char]
                # find closest j to idx
                j_idx = bisect.bisect_left(pos_list, idx)
                if j_idx == 0:
                    j = pos_list[0]
                elif j_idx == len(pos_list):
                    j = pos_list[-1]
                else:
                    # compare with both neighbors
                    left = pos_list[j_idx - 1]
                    right = pos_list[j_idx]
                    if abs(idx - left) <= abs(idx - right):
                        j = left
                    else:
                        j = right
                total += abs(idx - j)
        print(total)

if __name__ == '__main__':
    solve()
"}

