import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    x = int(next(it))
    y = int(next(it))
    x0 = int(next(it))
    y0 = int(next(it))
    s = next(it)

    visited = [[-1] * y for _ in range(x)]

    # Convert to 0-indexed
    cx, cy = x0 - 1, y0 - 1
    visited[cx][cy] = 0

    for i, ch in enumerate(s):
        newx, newy = cx, cy
        if ch == 'U':
            newx = cx - 1
        elif ch == 'D':
            newx = cx + 1
        elif ch == 'L':
            newy = cy - 1
        elif ch == 'R':
            newy = cy + 1
        else:
            pass  # should not happen

        if 0 <= newx < x and 0 <= newy < y:
            if visited[newx][newy] == -1:
                visited[newx][newy] = i + 1  # step i+1 (1..len(s))
            cx, cy = newx, newy
        else:
            # robot stays; if current position unvisited at this step
            if visited[cx][cy] == -1:
                visited[cx][cy] = i + 1

    # count
    count = [0] * (len(s) + 1)
    for v in visited:
        for val in v:
            if val != -1:
                count[val] += 1
    count[len(s)] += x * y - sum(count)  # unvisited

    sys.stdout.write(' '.join(map(str, count)))

if __name__ == "__main__":
    solve()
"}

