            if visited[cx][cy] == -1:
                visited[cx][cy] = i + 1

    # count
    count = [0] * (len(s) + 1)
    for v in visited:
        for val in v:
            if val != -1:
                count[val] += 1
    count[len(s)] += x * y - sum(count)  # unvisited

    sys.stdout.write(' '.join(map(str, count)))

if __name__ == "__main__":
    solve()

