def normalize(dx, dy):
    """Normalize direction vector to its simplest form."""
    if dx == 0 and dy == 0:
        # This shouldn't happen since no stormtrooper is at the same point as the gun
        return (0, 0)

    if dx == 0:
        # Vertical line
        return (0, 1)
    elif dy == 0:
        # Horizontal line
        return (1, 0)

    g = math.gcd(abs(dx), abs(dy))
    dx //= g
    dy //= g

    # Ensure consistent direction: if dx < 0, negate both components
    if dx < 0:
        dx = -dx
        dy = -dy

    return (dx, dy)

n, x0, y0 = map(int, input().split())

lines = set()

for _ in range(n):
    xi, yi = map(int, input().split())
    dx = xi - x0
    dy = yi - y0
    normalized = normalize(dx, dy)
    lines.add(normalized)

print(len(lines))
"}

