def solve():
    k, b, n, t = map(int, sys.stdin.read().split())

    # Calculate z from first experiment
    if k == 1:
        # z = 1 + b * n
        z = 1 + b * n
    else:
        # z = k^n + b * (k^n - 1) / (k - 1)
        power_k_n = pow(k, n)
        z = power_k_n + b * (power_k_n - 1) // (k - 1)

    # Find minimum m in second experiment
    if k == 1:
        # After m seconds: t + b * m
        m = max(0, (z - t + b - 1) // b)  # Ceiling division
    else:
        m = 0
        current = t
        while current < z:
            current = k * current + b
            m += 1

    print(m)

if __name__ == "__main__":
    solve()
