def is_dominated(arr):
    """Check if a subarray is dominated"""
    freq = {}
    max_freq = 0
    max_other = 0

    for num in arr:
        freq[num] = freq.get(num, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Check if any value has this max frequency
    count_max = 0
    for val in freq.values():
        if val == max_freq:
            count_max += 1

    # Check if the max frequency is strictly greater than all other frequencies
    # There should be exactly one value with this max frequency (since otherwise it's not dominated)
    if count_max == 1 and max_freq > max(freq.values(), default=0):  # Default for max(())
        return True
    return False

