import sys

def solve():
    MOD = 998244353
    n, m = map(int, sys.stdin.readline().split())
    a = list(map(int, sys.stdin.readline().split()))

    # dp[mask] = number of ways to get XOR value mask
    max_mask = 1 << m
    dp = [0] * max_mask
    dp[0] = 1

    for v in a:
        new_dp = dp.copy()
        for mask in range(max_mask):
            if dp[mask]:
                new_dp[mask ^ v] = (new_dp[mask ^ v] + dp[mask]) % MOD
        dp = new_dp

    # Now count number of subsets with each bit count
    result = [0] * (m + 1)
    for mask in range(max_mask):
        if dp[mask]:
            bits = bin(mask).count('1')
            result[bits] = (result[bits] + dp[mask]) % MOD

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
