import sys
sys.setrecursionlimit(1 << 25)

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    # Tarjan's algorithm to find bridges
    visited = [False] * (n + 1)
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    time = [1]
    bridges = []
    parent = [-1] * (n + 1)

    def dfs(u):
        visited[u] = True
        disc[u] = low[u] = time[0]
        time[0] += 1

        for v in graph[u]:
            if v == parent[u]:
                continue

            if not visited[v]:
                parent[v] = u
                dfs(v)
                low[u] = min(low[u], low[v])

                # Check if the edge u-v is a bridge
                if low[v] > disc[u]:
                    bridges.append((u, v))
            else:
                low[u] = min(low[u], disc[v])

    for u in range(1, n + 1):
        if not visited[u]:
            dfs(u)

    if len(bridges) > 0:
        print(0)
        return

    # If 2-edge-connected, find ear decomposition
    # Use DFS to orient edges
    oriented = set()
    visited = [False] * (n + 1)

    def dfs_orient(u, prev):
        visited[u] = True

        for v in graph[u]:
            if v == prev:
                continue

            edge = tuple(sorted((u, v)))
            if edge not in oriented:
                oriented.add(edge)
                # Orient based on direction of traversal
                if not visited[v]:
                    dfs_orient(v, u)
                    print(u, v)
                else:
                    print(v, u)

    dfs_orient(1, -1)

    for edge in oriented:
        print(*edge)

if __name__ == "__main__":
    solve()
