def solve():
    n = int(input())
    crossword = input().strip()
    m = int(input())
    words = []
    for _ in range(m):
        parts = input().split()
        words.append((parts[0], int(parts[1])))
    x = int(input())

    # DP: dp[i][mask] = max points from position i to end
    # mask: bitset where bit j is 1 if position j is used up
    # Since n <= 500, mask needs 500 bits

    from collections import defaultdict

    # dp[i] = dictionary mapping masks to max points
    dp = [defaultdict(int) for _ in range(n + 1)]

    # Base case: after last position
    dp[n][0] = 0

    for i in range(n - 1, -1, -1):
        # First, carry over from position i+1 without using any word
        for mask, points in dp[i+1].items():
            dp[i][mask] = max(dp[i][mask], points)

        # Now try to match words at position i
        for word, pts in words:
            if crossword.startswith(word, i):
                k = i + len(word) - 1
                if k >= n:
                    continue

                # For each possible mask at position i
                for mask, points in dp[i].items():
                    all_available = True
                    for pos in range(i, k + 1):
                        if (mask >> pos) & 1 == 1:
                            all_available = False
                            break

                    if all_available:
                        new_mask = mask
                        for pos in range(i, k + 1):
