    n = int(input())
    crossword = input().strip()
    m = int(input())
    words = []
    for _ in range(m):
        parts = input().split()
        words.append((parts[0], int(parts[1])))
    x = int(input())

    from collections import defaultdict

    # dp[i] = dictionary mapping masks to max points
    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[n][0] = 0

    for i in range(n - 1, -1, -1):
        # Carry over states from position i+1 without using a word
        for mask, points in dp[i+1].items():
            dp[i][mask] = max(dp[i][mask], points)

        # Make a copy of current states to avoid changing during iteration
        current_states = list(dp[i].items())

        for mask, points in current_states:
            for word, pts in words:
                if crossword.startswith(word, i):
                    k = i + len(word) - 1
                    if k >= n:
                        continue

                    all_available = True
                    for pos in range(i, k + 1):
                        if (mask >> pos) & 1 == 1:
                            all_available = False
                            break

                    if all_available:
                        new_mask = mask
                        for pos in range(i, k + 1):
                            new_mask |= (1 << pos)
                        dp[i][new_mask] = max(dp[i][new_mask], points + pts)

    max_pts = 0
    for mask, pts in dp[0].items():
        max_pts = max(max_pts, pts)

    print(max_pts)

solve()
