MOD = 10**9 + 7

def solve():
    n, k = map(int, input().split())

    # Build tree
    tree = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u, v = map(int, input().split())
        tree[u].append(v)
        tree[v].append(u)

    # dp[v][d] = number of ways to paint subtree rooted at v with coverage distance d
    dp = [{} for _ in range(n + 1)]

    def dfs(v, parent):
        # Base case: leaf node (only has parent)
        if len(tree[v]) == 1:
            # v has no children, only its parent
            dp[v][0] = 1  # paint v black
            if 1 <= k:
                dp[v][1] = 1  # parent is black
            return

        # For a non-leaf node, we need to consider all children
        # dp[v][0] = ways where v is black
        dp[v][0] = 1  # Paint v black

        # dp[v][d] = ways where v is not black but has coverage distance d
        for d in range(1, k + 1):
            dp[v][d] = 0

        # Combine with children
        for neighbor in tree[v]:
            if neighbor == parent:
                continue
            # Get ways from this child
            child_dp = dp[neighbor]

            # If v is black, its children have coverage distance 0
            # So we multiply ways where v is black with child ways
            if 0 in dp[v]:
                for d, ways in child_dp.items():
                    dp[v][d] = (dp[v][d] + dp[v][0] * ways) % MOD

            # If v is not black, we need to match coverage distances
            for d_v in dp[v]:
                if d_v == 0:
                    continue  # v is black
                if d_v > k:
                    continue

                for d_c, ways_c in child_dp.items():
                    if d_v + 1 == d_c:
                        dp[v][d_v + 1] = (dp[v][d_v + 1] + dp[v][d_v] * ways_c) % MOD


    # Pick a root (say 1)
    dfs(1, -1)

    # The answer is dp[root][0] + dp[root][1] + ... + dp[root][k]
    result = sum(dp[1][d] for d in range(k + 1)) % MOD
    print(result)

solve()
"}

