x, y, x0, y0 = map(int, input().split())
s = input()

# Precompute the robot's position after each command
positions = [(x0, y0)]  # positions[0] = initial position
x_pos = x0
y_pos = y0

for c in s:
    if c == 'L':
        y_pos -= 1
    elif c == 'R':
        y_pos += 1
    elif c == 'U':
        x_pos -= 1
    elif c == 'D':
        x_pos += 1

    positions.append((x_pos, y_pos))

# Count how many tests end at each position after k commands
result = [0] * (len(s) + 1)

# Consider all mine positions
for mine_x in range(1, x + 1):
    for mine_y in range(1, y + 1):
        found = False
        for k in range(len(positions)):
            if positions[k] == (mine_x, mine_y):
                found = True
                break

        if found:
            result[k] += 1
        else:
            # The robot never hits the mine, so it completes all commands
            result[len(s)] += 1

# Print the result
print(' '.join(map(str, result)))
