def solve():
    n, m = map(int, input().split())
    playlist = list(map(int, input().split()))

    # Count how many times each band in 1..m appears
    count = [0] * (m + 1)
    for band in playlist:
        if 1 <= band <= m:
            count[band] += 1

    # Find the maximum value ans such that we can make each band appear at least ans times
    # We need m * ans songs total, and we have n songs
    ans = n // m

    # Now, we want to minimize changes
    # We'll iterate through the playlist and assign bands
    result = []

    # First, fill in bands that are already in 1..m
    for i in range(n):
        band = playlist[i]
        if 1 <= band <= m:
            if count[band] < ans:
                result.append(band)
                count[band] += 1
            else:
                # This band is already at capacity
                # We can assign it to a band that's not yet at capacity
                for j in range(1, m + 1):
                    if count[j] < ans:
                        result.append(j)
                        count[j] += 1
                        break
        else:
            # Band outside 1..m, we need to assign it to a band that's not yet at capacity
            for j in range(1, m + 1):
                if count[j] < ans:
                    result.append(j)
                    count[j] += 1
                    break

    print(ans, n - sum(count))
    print(' '.join(map(str, result)))

solve()
