q = int(input())
for _ in range(q):
    # Skip empty line before each test case
    while True:
        try:
            line = input()
        except:
            break
        if line.strip() == '':
            break

    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    t = list(map(int, input().split()))

    # Sort air conditioners by position
    air = sorted(zip(a, t))

    # Left-to-right pass: minimize t_j + |a_j - i|
    ans = [0] * n
    left = right = 0

    for i in range(1, n + 1):
        # Check if we should switch to a later air conditioner
        # Left side: cost = (t_j + a_j) - i
        cost_left = air[left][1] + air[left][0] - i

        # Right side: cost = (t_j - a_j) + i
        if right < len(air):
            cost_right = air[right][1] - air[right][0] + i
        else:
            # No more air conditioners to the right
            cost_right = float('inf')

        # Choose the minimum cost
        if cost_left <= cost_right:
            ans[i - 1] = cost_left
            # Move right if we need to
            if i == air[right][0] and right < len(air):
                right += 1
        else:
            ans[i - 1] = cost_right
            # Move left if we need to
            if i == air[left][0] + 1 and left < len(air) - 1:
                left += 1

    print(' '.join(map(str, ans)))
"}

