import sys

def solve() -> None:
    input = sys.stdin.read().split()
    if not input:
        return

    # Parse the input
    it = iter(input)
    q = int(next(it))

    for _ in range(q):
        # Skip empty lines
        while True:
            try:
                token = next(it)
                if token != '':
                    break
            except StopIteration:
                break

        n, k = int(next(it)), int(next(it))
        a = list(map(int, [next(it) for _ in range(k)]))
        t = list(map(int, [next(it) for _ in range(k)]))

        # Initialize array of size n+2 for prefix sums
        arr = [0] * (n + 2)

        # Add contributions from each air conditioner
        for ai, ti in zip(a, t):
            arr[ai] += ti
            for j in range(ai + 1, n + 1):
                arr[j] += ti

        # Compute prefix sums to get minimum temperatures
        res = []
        curr = 0
        for i in range(1, n + 1):
            curr += arr[i]
            res.append(str(curr))

        # Print result
        print(' '.join(res))

if __name__ == "__main__":
    solve()
