def can_win(s):
    """Determine if we can get 2048 from a multiset of powers of 2"""
    # Count how many of each power of 2 we have
    counts = {}
    for num in s:
        # Find the exponent: 2^e = num
        e = num.bit_length() - 1
        counts[e] = counts.get(e, 0) + 1

    # We need at least 2 of every power from 1 to 10 to be able to combine upwards
    # To get 2048 (2^11), we need at least 2 of 1024 (2^10)
    # To get 2 of 1024, we need at least 4 of 512 (2^9)
    # And so on down to 2^1 needing 2 of 2^0

    # Starting from the smallest power, we need at least 2 of each
    for e in range(1, 11):
        if e not in counts or counts[e] < 2:
            return False

    return True

q = int(input())
for _ in range(q):
    n = int(input())
    s = list(map(int, input().split()))

    if can_win(s):
        print("YES")
    else:
        print("NO")
