def can_win(s):
    """Determine if we can get 2048 from a multiset of powers of 2"""
    # Count how many of each power of 2 we have
    counts = {}
    for num in s:
        # Find the exponent: 2^e = num
        e = num.bit_length() - 1
        counts[e] = counts.get(e, 0) + 1

    # We need to determine if we can get 2 of every power from 0 to 10
    # We can use the fact that if we have at least one of a power, we can treat it
    # as if we have 1 extra of the lower power

    # Starting from the smallest power, we need at least 2
    # If we have at least 1, we can use it to help get 2 of the next lower power
    needed = {}  # Track how many of each power we need to win

    # Start from the highest power and work down
    needed[11] = 1  # Need 1 of 2048

    for power in range(11, 0, -1):
        if power in needed:
            # Need to get some of this power
            needed_pairs = needed[power]

            # Check if we have enough of the lower power
            if power - 1 in counts:
                have = counts[power - 1]

                # If we have enough, we can get needed_pairs of this power
                if have >= needed_pairs:
                    needed[power] -= needed_pairs
                    if needed[power] <= 0:
                        del needed[power]

                # If we have exactly needed_pairs, we need the next power
                elif have == needed_pairs:
                    needed[power] = 1

            # If we don't have the lower power and needed_pairs > 0, we need the next power
            elif needed_pairs > 0:
                needed[power] = 1

    # If we still need 2048, we can't win
    return 2048 not in needed

