def solve():
    T = int(input())
    for _ in range(T):
        n = int(input())
        a = list(map(int, input().split()))
        min_len = float('inf')

        # Try all possible values in the array
        for val in set(a):
            # Use two pointers approach to find smallest window dominated by val
            left = 0
            val_count = 0
            other_max_count = 0

            for right in range(n):
                if a[right] == val:
                    val_count += 1
                else:
                    other_max_count = max(other_max_count, 1)

                # Check if current window is dominated
                # We only need to check when window size is at least 2
                # Actually, we need to be careful about window shrinkage

                # When val_count > other_max_count, we have a valid window
                while val_count > other_max_count and left <= right:
                    if right - left + 1 < min_len:
                        min_len = right - left + 1

                    # Try to shrink window
                    if a[left] == val:
                        val_count -= 1
                    else:
                        other_max_count -= 1
                    left += 1

        print(min_len if min_len != float('inf') else -1)

solve()
