def solve(s):
    points = list(s)
    n = len(points)
    operations = 0

    while True:
        # Step 1: Find which points will be deleted
        to_delete = set()

        for i in range(n):
            # Check if this point has a different neighbor on the left
            if i > 0 and points[i-1] != points[i]:
                to_delete.add(i)
            # Check if this point has a different neighbor on the right
            if i < n - 1 and points[i+1] != points[i]:
                to_delete.add(i)

        # Step 2: Check if any points are deleted
        if not to_delete:
            break

        operations += 1

        # Step 3: Keep only the points that are not deleted
        remaining = []
        for i in range(n):
            if i not in to_delete:
                remaining.append(points[i])

        # Step 4: Update points list
        points = remaining
        n = len(points)

    print(operations)

# Read input and output result
test_cases = [
    "aabb",
    "aabcaa",
]

for case in test_cases:
    solve(case)
