import sys

def input():
    return sys.stdin.readline().strip()

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    m = int(next(it))
    queries = []
    for _ in range(m):
        w = int(next(it))
        h = int(next(it))
        queries.append((w, h))

    # Segment tree for range max and range assign
    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.max_tree = [0] * (2 * self.size)
            self.lazy = [None] * (2 * self.size)
            for i in range(self.n):
                self.max_tree[self.size + i] = data[i]
            for i in range(self.size - 1, 0, -1):
                self.max_tree[i] = max(self.max_tree[2 * i], self.max_tree[2 * i + 1])

        def _apply(self, node, value):
            self.max_tree[node] = value
            self.lazy[node] = value

        def _push(self, node, l, r):
            if self.lazy[node] is not None and node < self.size:
                self._apply(2 * node, self.lazy[node])
                self._apply(2 * node + 1, self.lazy[node])
                self.lazy[node] = None

        def range_assign(self, a, b, val, node=1, l=0, r=None):
            if r is None:
                r = self.size - 1
            if a > r or b < l:
                return
            if a <= l and r <= b:
                self._apply(node, val)
                return
            self._push(node, l, r)
            mid = (l + r) // 2
            self.range_assign(a, b, val, 2 * node, l, mid)
            self.range_assign(a, b, val, 2 * node + 1, mid + 1, r)
            self.max_tree[node] = max(self.max_tree[2 * node], self.max_tree[2 * node + 1])

        def range_max(self, a, b, node=1, l=0, r=None):
            if r is None:
                r = self.size - 1
            if a > r or b < l:
                return -float('inf')
            if a <= l and r <= b:
                return self.max_tree[node]
            self._push(node, l, r)
            mid = (l + r) // 2
            left = self.range_max(a, b, 2 * node, l, mid)
            right = self.range_max(a, b, 2 * node + 1, mid + 1, r)
            return max(left, right)

    # We use 0-indexed array
    tree = SegmentTree(a)
    for w, h in queries:
        bottom = tree.range_max(0, w - 1)
