def solve_johnny(n, k):
    """Try to find a long path for Johnny"""
    visited = [False] * (n + 1)
    path = []

    def dfs(vertex):
        if len(path) >= n // k:
            return True

        if visited[vertex]:
            return False

        visited[vertex] = True
        path.append(vertex)

        # Try all neighbors
        for neighbor in adj[vertex]:
            if dfs(neighbor):
                return True

        # Backtrack
        visited[vertex] = False
        path.pop()
        return False

    if dfs(1):
        return "PATH", len(path), path

    return None


def solve_solving(n, k, adj):
    """Try to find k cycles for Solving"""
    # Find k cycles with length not divisible by 3 and unique representatives
    cycles = []
    visited = [False] * (n + 1)

    def dfs_cycle(start, cycle, representative):
        if len(cycle) >= 3 and len(cycle) % 3 != 0:
            # Found a valid cycle
            cycles.append((len(cycle), cycle + [representative]))  # Add representative at end
            return True

        if visited[start]:
            return False

        visited[start] = True
        cycle.append(start)

        # Try all neighbors
        for neighbor in adj[start]:
            # If we're at the representative, we need to return
            if cycle and start == representative:
                visited[start] = False
                cycle.pop()
                return False

            # Avoid immediate backtracking
            if start == cycle[0]:
                continue

            if dfs_cycle(neighbor, cycle, representative):
                return True

        # Backtrack
        visited[start] = False
        cycle.pop()
        return False

    # Try to find cycles
    for i in range(k):
        found = False
        # Try all vertices as potential starting points
        for start in range(1, n + 1):
            if not visited[start]:
                cycle = [start]
                # Try to find a cycle starting at this vertex
                if dfs_cycle(start, cycle, start):
                    found = True
                    break

        if not found:
            return None

    # Build output
    output = ["CYCLES"]
    for size, cycle in cycles:
        output.append(str(size))
        output.append(" ".join(map(str, cycle)))
    return output


