    right_actor = [[False]*m for _ in range(n)]
    for i in range(n):
        has_actor = False
        for j in range(m-1, -1, -1):
            right_actor[i][j] = has_actor
            if grid[i][j] == 1:
                has_actor = True

    # up_actor[i][j] = any actor above (i,j) in the same column
    up_actor = [[False]*m for _ in range(n)]
    for j in range(m):
