    c.update(frag)

# Build graph of order constraints
from collections import defaultdict, deque

g = defaultdict(set)
# In-degree for each node
in_degree = defaultdict(int)

for frag in fragments:
    if len(frag) > 1:
        for i in range(len(frag) - 1):
            u = frag[i]
            v = frag[i + 1]
            if v not in g[u]:
                g[u].add(v)
                in_degree[v] += 1

# If no constraints, just output characters in sorted order
if not g:
    result = ''.join(sorted(c))
else:
    # Kahn's algorithm for topological sort
    result = []
    queue = deque([char for char in c if in_degree.get(char, 0) == 0])

    while queue:
        node = queue.popleft()
        result.append(node)

        for neighbor in g[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

print(''.join(result))
