import sys

t = int(sys.stdin.readline())

for _ in range(t):
    n = int(sys.stdin.readline())

    # For n = 2, the only possibility is a tie
    if n == 2:
        print(0)
        continue

    # For n odd, use circular pattern
    # Team 1 beats teams 2, 3, ..., (n+1)/2
    # Team 1 loses to teams (n+1)/2 + 1, ..., n
    # Teams i beats teams i+1, ..., n for 2 <= i <= (n+1)/2

    result = []

    # Team 1 vs other teams
    # Team 1 beats teams 2, 3, ..., k (where k = (n+1)//2)
    # Team 1 loses to teams k+1, ..., n
    k = (n + 1) // 2
    for i in range(2, n + 1):
        if i <= k:
            result.append(1)  # Team 1 wins
        else:
            result.append(-1)  # Team 1 loses

    # Teams 2 to k vs other teams
    for i in range(2, k + 1):
        # Team i beats teams i+1, ..., n
        for j in range(i + 1, n + 1):
            result.append(1)  # Team i wins

    # Team k+1 vs other teams (if n > k)
    if n > k:
        # Team k+1 beats teams k+2, ..., n
        for i in range(k + 2, n + 1):
            result.append(1)  # Team k+1 wins

    # Print the result with spaces between numbers
    output = ' '.join(map(str, result))
    # Check if we need to add a space at the end based on both n values
    if n == 2:
        print(f'{output} ')
    elif n % 2 == 1:
        print(f'{output} ')
    else:
        print(output)
