def solve():
    n = int(input())
    c = list(input())
    a = list(input())

    half = n // 2

    # Try all possible subsets of size n//2
    # We'll use a backtracking approach with pruning

    def backtrack(start_idx, count, selected, clowns_count, acrobats_count):
        if count == half:
            if clowns_count == acrobats_count:
                return selected[:]
            return None

        # Try selecting each artist from start_idx to n-1
        for i in range(start_idx, n):
            # Prune if not enough artists left
            if count + (n - i) < half:
                continue

            selected.append(i + 1)
            count += 1

            # Update counts
            if c[i] == '1':
                clowns_count += 1
            if a[i] == '1':
                acrobats_count += 1

            result = backtrack(i + 1, count, selected, clowns_count, acrobats_count)
            if result is not None:
                return result

            selected.pop()
            count -= 1
            if c[i] == '1':
                clowns_count -= 1
            if a[i] == '1':
                acrobats_count -= 1

        return None

    # Try all possible starting positions
    for start_idx in range(n):
        result = backtrack(start_idx, 0, [], 0, 0)
        if result:
            print(' '.join(map(str, result)))
            return

    print(-1)

solve()
