import heapq

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    n, k = int(data[0]), int(data[1])
    a = list(map(int, data[2:2+n]))
    heap = []
    for i in range(n):
        heapq.heappush(heap, (-a[i], i + 1))
    available = [True] * (n + 2)
    result = [''] * n
    turn = 1
    while heap:
        while heap:
            skill_neg, pos = heapq.heappop(heap)
            skill = -skill_neg
            if not available[pos]:
                continue
            else:
                break
        # found max at pos
        left = max(1, pos - k)
        right = min(n, pos + k)
        for i in range(left, right + 1):
            if available[i]:
                available[i] = False
                result[i - 1] = '1' if turn else '2'
        turn ^= 1

    print(''.join(result))

if __name__ == '__main__':
    main()
"}

