def find_matching(n, m, edges):
    match = [False] * (n + 1)
    result = []

    # Try to find a matching of size n greedily
    for i in range(1, m + 1):
        v, u = edges[i-1]
        if not match[v] and not match[u]:
            result.append(i)
            match[v] = match[u] = True

    if len(result) >= n:
        return "Matching", result[:n]

    # Try to find an independent set

    # First find a matching of size n-1
    match = [False] * (n + 1)
    result = []

    for i in range(1, m + 1):
        v, u = edges[i-1]
        if not match[v] and not match[u]:
            result.append(i)
            match[v] = match[u] = True

    # The vertices not matched form an independent set
    not_matched = [v for v in range(1, 3*n + 1) if not match[v]]

    # Remove vertices with degree > 1
    degree = [0] * (3*n + 1)
    for v, u in edges:
        degree[v] += 1
        degree[u] += 1

    independent_set = []

    # Try to find an independent set greedily
    for v in not_matched:
        if degree[v] <= 1 and v not in independent_set:
            independent_set.append(v)

    # If we still haven't found n vertices, we need a different approach
    # Try to find an independent set by iterating through all vertices
    if len(independent_set) < n:
        result = []
        for v in range(1, 3*n + 1):
            if degree[v] <= 1 and v not in independent_set:
                result.append(v)
                independent_set.append(v)

    # If we still haven't found n vertices, we need to find an independent set
    # by iteratively removing vertices with degree > 1
    while len(independent_set) < n:
        for v in range(1, 3*n + 1):
            if degree[v] > 1 and v not in independent_set:
                result.append(v)
                independent_set.append(v)

    return "IndSet", independent_set[:n]

