def compute_min_max_sum(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b, t in edges:
        adj[a].append((b, t))
        adj[b].append((a, t))

    # Function to compute distance between two nodes
    def distance(u, v):
        dist = [float('inf')] * (n + 1)
        dist[u] = 0

        # Use a priority queue for Dijkstra's algorithm
        heap = [(0, u)]

        while heap:
            d, current = heapq.heappop(heap)
            if d > dist[current]:
                continue
            for neighbor, w in adj[current]:
                if dist[neighbor] > dist[current] + w:
                    dist[neighbor] = dist[current] + w
                    heapq.heappush(heap, (dist[neighbor], neighbor))
        return dist[v]

    # For minimum sum: pair nodes by sorting edges by weight
    min_edges = sorted(edges, key=lambda e: e[2])
    min_sum = 0

    # Keep track of paired nodes
    paired = [False] * (n + 1)

    for a, b, t in min_edges:
        if not paired[a] and not paired[b]:
            min_sum += t
            paired[a] = True
            paired[b] = True
        elif not paired[a]:
            # Pair a with a nearby unpaired node
            for v, w in adj[a]:
                if not paired[v] and v > a:
                    min_sum += w
                    paired[a] = True
                    paired[v] = True
                    break
        elif not paired[b]:
            # Pair b with a nearby unpaired node
            for v, w in adj[b]:
                if not paired[v] and v > b:
                    min_sum += w
                    paired[b] = True
                    paired[v] = True
                    break

    # For maximum sum: pair nodes by sorting edges by weight (reverse)
    max_edges = sorted(edges, key=lambda e: e[2], reverse=True)
    max_sum = 0

    paired = [False] * (n + 1)

    for a, b, t in max_edges:
        if not paired[a] and not paired[b]:
            max_sum += t
            paired[a] = True
            paired[b] = True
        elif not paired[a]:
            # Pair a with a nearby unpaired node
            for v, w in adj[a]:
                if not paired[v] and v > a:
                    max_sum += w
                    paired[a] = True
                    paired[v] = True
                    break
        elif not paired[b]:
            # Pair b with a nearby unpaired node
            for v, w in adj[b]:
                if not paired[v] and v > b:
                    max_sum += w
                    paired[b] = True
                    paired[v] = True
                    break

    return min_sum, max_sum

