import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx])
    m = int(data[idx + 1])
    idx += 2

    edges = []
    for _ in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # DFS to find a spanning tree and orient edges
    parent = [0] * (n + 1)
    visited = [False] * (n + 1)

    # Simple DFS
    stack = [(1, 0)]  # (current node, parent)
    while stack:
        node, p = stack.pop()
        if visited[node]:
            continue
        visited[node] = True
        parent[node] = p

        # Process all neighbors
        for neighbor in adj[node]:
            if not visited[neighbor]:
                stack.append((neighbor, node))
            elif neighbor != p:
                # This is a back edge
                pass  # We'll handle later

    # If we didn't visit all nodes, it's disconnected
    if sum(visited[1:]) != n:
        sys.stdout.write("0\n")
        return

    # Check if we have at least one back edge
    back_edges = []
