    idx = 1

    results = []

    for _ in range(t):
        n = int(data[idx])
        m = int(data[idx + 1])
        idx += 2

        a = list(map(int, data[idx:idx + n]))
        idx += n

        # Greedy grouping: try to add to the last array
        groups = []
        for num in a:
            r = num % m
            if groups:
                # Try to add to the last group
                last_r = groups[-1][-1] % m
                if (last_r + r) % m == 0:
                    groups[-1].append(num)
                else:
                    groups.append([num])
            else:
                groups.append([num])

        results.append(str(len(groups)))

