def cyclic_shift(a, L, R):
    if L == R:
        return
    a[L-1], a[R-1] = a[R-1], a[L-1]
    for i in range(L, R):
        a[i-1], a[i] = a[i], a[i-1]


def reverse_segment(a, L, R):
    L_idx = L - 1
    R_idx = R - 1
    while L_idx < R_idx:
        a[L_idx], a[R_idx] = a[R_idx], a[L_idx]
        L_idx += 1
        R_idx -= 1


