import math

def determine_color(x, y):
    distance_squared = x*x + y*y
    distance = math.sqrt(distance_squared)

    if distance.is_integer():
        # Distance is an integer, so black
        return "black"

    # Distance is not an integer
    integer_part = int(distance)

    # If either x or y is negative, white; if both positive, black
    if x < 0 or y < 0:
        return "white" if integer_part % 2 == 0 else "black"
    else:
        return "black" if integer_part % 2 == 0 else "white"

def main():
    x, y = map(int, input().split())
    print(determine_color(x, y))

if __name__ == "__main__":
    main()
"}

