import sys

def solve():
    x = sys.stdin.readline().strip()
    if not x:
        return

    res = []
    for i, ch in enumerate(x):
        d = int(ch)
        if i == 0:
            # first digit, cannot be 0
            inv = 9 - d
            if inv == 0:
                # inversion gives 0, can't use, must use original
                res.append(str(d))
            else:
                # choose min(original, inversion)
                res.append(str(min(d, inv)))
        else:
            # non-first, choose min(d, 9-d)
            res.append(str(min(d, 9 - d)))

    print(''.join(res))

if __name__ == '__main__':
    solve()
"}

