for _ in range(t):
    n = int(input())
    s = list(map(int, input().split()))

    # dp[i] = maximum length of beautiful sequence ending at index i (1-indexed)
    dp = [1] * n

    # For each index i (1-indexed), we need to consider its divisors
    for i in range(1, n + 1):
        # Check all multiples of i
        for j in range(2 * i, n + 1, i):
            if s[j - 1] > s[i - 1]:
                if dp[j - 1] + 1 > dp[i - 1]:
                    dp[i - 1] = dp[j - 1] + 1

    print(max(dp))
