    for i in range(j):
        if s[i] < s[j]:
            min_left[j] = min(min_left[j], c[i])

# For each position j, find minimum cost to the right with larger font size
for j in range(n):
    for k in range(j + 1, n):
        if s[k] > s[j]:
            min_right[j] = min(min_right[j], c[k])

# Find minimum valid total cost
min_total = float('inf')
for j in range(n):
    if min_left[j] != float('inf') and min_right[j] != float('inf'):
        total = min_left[j] + c[j] + min_right[j]
        min_total = min(min_total, total)

