import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    s = list(map(int, (next(it) for _ in range(n))))
    c = list(map(int, (next(it) for _ in range(n))))

    min_total = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if s[i] < s[j] and s[j] < s[k]:
                    total = c[i] + c[j] + c[k]
                    if total < min_total:
                        min_total = total

    print(min_total if min_total != float('inf') else -1)

if __name__ == "__main__":
    solve()
